// build-code-frameworks-010-jest-load-fixed: A Jest file that cannot load its missing service is one load member; build code plans and applies a repair, reruns the file by path and ends green
func TestBuildCodeFrameworks010JestLoadFixed(t *testing.T) {
	s := scenarios.New(t, "build-code-frameworks-010-jest-load-fixed")
	s.Given(`the "build-code-jest-load" project tree`)
	s.And(`the project's test dependencies are installed`)
	s.And(`the System Architect's answer to every question is "1"`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 0`)
	s.And(`stdout matches msg="Suite failures" failures=1 framework=jest`)
	s.And(`stdout matches tests\.unit\.greeting\.test\.js::<load>`)
	s.And(`stdout matches msg="Fix applied; re-running the failing set"`)
	s.And(`stdout matches BUILD CODE COMPLETE`)
	s.And(`the file "services/greeter/greeting.js" is created`)
	s.And(`the engine spawned a test runner with arguments matching --runTestsByPath .*/tests/unit/greeting\.test\.js`)
	s.And(`the engine dispatched 1 fix AI turn to "claude"`)
	s.And(`the engine dispatched 1 apply AI turn to "codex"`)
	s.But(`the file "tests/unit/greeting.test.js" is unchanged`)
	s.And(`the file "docs/architecture/architecture.yaml" is unchanged`)
	s.And(`the shell command "npx jest --json --config jest.config.js" run in "tests" exits with code 0`)
	s.Done()
}

// build-code-frameworks-011-command-fails-without-member: A failing Jest command with no tests to name stops build code before any AI turn, naming the command and exit code without a completion banner
func TestBuildCodeFrameworks011CommandFailsWithoutMember(t *testing.T) {
	s := scenarios.New(t, "build-code-frameworks-011-command-fails-without-member")
	s.Given(`the "build-code-jest-no-tests" project tree`)
	s.And(`the project's test dependencies are installed`)
	s.When(`the System Architect runs "build code --fix"`)
	s.Then(`the command exits with code 1`)
	s.And(`stdout matches npx jest --json --config jest.config.js`)
	s.And(`stdout matches exited with code 1`)
	s.And(`stdout matches No tests found`)
	s.And(`stdout does not match BUILD CODE COMPLETE`)
	s.And(`the engine dispatched no AI turns`)
	s.But(`no file outside "tmp" changed`)
	s.Done()
}
